/// receive restock notifications, and move items to their shopping cart when
/// ready to purchase. The system prevents duplication of the same product
/// variant within a single wishlist.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_wishlist_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Belonged wishlist's {@link shopping_mall_wishlists.id}
  ///
  /// Foreign key linking the item to its parent wishlist.
  shopping_mall_wishlist_id String

  /// Referenced product variant's {@link shopping_mall_product_variants.id}
  ///
  /// Foreign key to the specific product variant being saved in the wishlist.
  shopping_mall_product_variant_id String

  /// Number of units the customer wants to save for this product variant.
  quantity Int?

  /// Timestamp when the item was added to the wishlist.
  created_at DateTime

  //----
  // RELATIONS
  //----
  wishlist       shopping_mall_wishlists        @relation(fields: [shopping_mall_wishlist_id], references: [id], onDelete: Cascade)
  productVariant shopping_mall_product_variants @relation(fields: [shopping_mall_product_variant_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_wishlist_id, shopping_mall_product_variant_id], map: "shopping_mall_wishlist_items_shopping_mall_wishlist_id_e2467ce3")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_variant_id], map: "shopping_mall_wishlist_items_shopping_mall_product_var_4a27a4f7")
}

/// Customer inquiries submitted through the platform for product information
/// or support. Inquiries enable customers to ask questions about products,
/// sellers, or platform services, supporting the marketplace's communication
/// needs. Each inquiry is created by a logged-in customer and may be
/// associated with specific sellers or products. Inquiries remain accessible
/// even after responses are provided, maintaining a complete conversation
/// history.
///
/// @namespace Inquiries
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_inquiries {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Customer who submitted the inquiry. {@link shopping_mall_customers.id}
  shopping_mall_customer_id String

  /// Customer's active session when submitting the inquiry. {@link
  /// shopping_mall_customer_sessions.id}
  shopping_mall_customer_session_id String

  /// Short descriptive title for the inquiry. Provides quick context for the
  /// question.
  title String

  /// Detailed content of the customer's inquiry. Contains the full question
  /// and any supporting details.
  body String

  /// Whether this inquiry should be kept private between customer and seller.
  /// Private inquiries are not visible to other users.
  secret Boolean

  /// Timestamp when the inquiry was first submitted.
  created_at DateTime

  /// Timestamp when the inquiry was last modified.
  updated_at DateTime

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers         @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)
  session  shopping_mall_customer_sessions @relation(fields: [shopping_mall_customer_session_id], references: [id], onDelete: Cascade)

  shopping_mall_inquiry_responses shopping_mall_inquiry_responses[]

  @@index([shopping_mall_customer_session_id])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_inquiries_shopping_mall_customer_id_crea_28c75a10")
  @@index([secret])
}

/// Seller responses to customer inquiries submitted on the platform. Each
